package workers

import (
	"context"
	"errors"
	"fmt"
	"sync"
)

// Job identifies a requested operation.
type Job int

// Lease supplies the existing cooperative operation and release boundary.
type Lease interface {
	Run(context.Context, Job) error
	Close() error
}

type outcome struct {
	err error
}

// Serve runs supplied jobs using leases acquired by the host. Capacity is
// retained until a lease's Close has completed.
func Serve(ctx context.Context, jobs <-chan Job, limit int, open func(context.Context, Job) (Lease, error)) error {
	if err := ctx.Err(); err != nil {
		return err
	}

	workCtx, stop := context.WithCancel(ctx)
	defer stop()
	capacity := make(chan struct{}, limit)
	var runs sync.WaitGroup
	results := make(chan error, limit)
	var errs []error
	stopping := false

	for !stopping {
		select {
		case <-ctx.Done():
			stopping = true
			errs = append(errs, ctx.Err())
			stop()
		case capacity <- struct{}{}:
			// A slot is reserved before reading a job, then returned if input ends.
			select {
			case <-ctx.Done():
				<-capacity
				stopping = true
				errs = append(errs, ctx.Err())
				stop()
			case job, ok := <-jobs:
				if !ok {
					<-capacity
					stopping = true
					break
				}
				runs.Add(1)
				go func(job Job) {
					defer runs.Done()
					lease, err := open(workCtx, job)
					if err != nil {
						results <- fmt.Errorf("open job %d: %w", job, err)
						stop()
						return
					}
					if lease == nil {
						results <- fmt.Errorf("open job %d returned a nil lease", job)
						stop()
						return
					}
					runErr := lease.Run(workCtx, job)
					closeErr := lease.Close()
					<-capacity
					if runErr != nil || closeErr != nil {
						results <- errors.Join(wrap("run", job, runErr), wrap("close", job, closeErr))
						stop()
					}
				}(job)
			}
		case err := <-results:
			errs = append(errs, err)
			stopping = true
			stop()
		}
	}

	// Stop requests have been sent. Join all admitted workers before returning;
	// workers release successful leases after Run has actually returned.
	runs.Wait()
	for {
		select {
		case err := <-results:
			errs = append(errs, err)
		default:
			if err := ctx.Err(); err != nil && !containsError(errs, err) {
				errs = append(errs, err)
			}
			return errors.Join(errs...)
		}
	}
}

func wrap(stage string, job Job, err error) error {
	if err == nil {
		return nil
	}
	return fmt.Errorf("%s job %d: %w", stage, job, err)
}

func containsError(errs []error, target error) bool {
	for _, err := range errs {
		if errors.Is(err, target) {
			return true
		}
	}
	return false
}

package workers

import (
	"context"
	"errors"
	"fmt"
	"sync"
)

// Job identifies a requested operation.
type Job int

// Lease supplies the existing cooperative operation and release boundary.
type Lease interface {
	Run(context.Context, Job) error
	Close() error
}

type event struct {
	job    Job
	lease  Lease
	err    error
	opened bool
}

// Serve runs supplied jobs using leases acquired by the host. At most limit
// leases are held, and all Runs in a cohort finish before any lease is closed.
func Serve(ctx context.Context, jobs <-chan Job, limit int, open func(context.Context, Job) (Lease, error)) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	workCtx, stop := context.WithCancel(ctx)
	defer stop()
	events := make(chan event, limit*2)
	var wg sync.WaitGroup
	var cohort []event
	var errs []error
	started := 0
	stopping, inputClosed := false, false

	for !stopping && !inputClosed && started < limit {
		if err := ctx.Err(); err != nil {
			errs = append(errs, err)
			stopping = true
			break
		}
		select {
		case <-ctx.Done():
			errs = append(errs, ctx.Err())
			stopping = true
			stop()
		case ev := <-events:
			if ev.opened {
				cohort = append(cohort, ev)
			}
			if ev.err != nil {
				errs = append(errs, ev.err)
				stopping = true
				stop()
			}
		case job, ok := <-jobs:
			if !ok {
				inputClosed = true
				break
			}
			started++
			wg.Add(1)
			go func(job Job) {
				defer wg.Done()
				lease, err := open(workCtx, job)
				if err != nil {
					events <- event{job: job, err: fmt.Errorf("open job %d: %w", job, err)}
					stop()
					return
				}
				if lease == nil {
					events <- event{job: job, err: fmt.Errorf("open job %d returned a nil lease", job)}
					stop()
					return
				}
				events <- event{job: job, lease: lease, opened: true}
				err = lease.Run(workCtx, job)
				events <- event{job: job, err: wrap("run", job, err)}
				if err != nil {
					stop()
				}
			}(job)
		}
	}
	if stopping {
		stop()
	}
	wg.Wait()
	for len(events) > 0 {
		ev := <-events
		if ev.opened {
			cohort = append(cohort, ev)
		}
		if ev.err != nil && !containsError(errs, ev.err) {
			errs = append(errs, ev.err)
		}
	}
	// Every started worker has returned, so no Run remains active.
	for _, item := range cohort {
		if err := item.lease.Close(); err != nil {
			errs = append(errs, fmt.Errorf("close job %d: %w", item.job, err))
		}
	}
	if err := ctx.Err(); err != nil && !containsError(errs, err) {
		errs = append(errs, err)
	}
	if len(errs) != 0 {
		return errors.Join(errs...)
	}
	if inputClosed {
		return nil
	}
	if started == limit {
		// Continue with the next cohort after all leases from this one close.
		return Serve(ctx, jobs, limit, open)
	}
	return nil
}

func wrap(stage string, job Job, err error) error {
	if err == nil {
		return nil
	}
	return fmt.Errorf("%s job %d: %w", stage, job, err)
}

func containsError(errs []error, target error) bool {
	for _, err := range errs {
		if errors.Is(err, target) {
			return true
		}
	}
	return false
}
package workers

import (
	"context"
	"errors"
	"sync"
	"testing"
	"time"
)

const waitBound = 5 * time.Second

func await[T any](t *testing.T, ch <-chan T, what string) T {
	t.Helper()
	select {
	case v := <-ch:
		return v
	case <-time.After(waitBound):
		t.Fatalf("timed out waiting for %s", what)
		var zero T
		return zero
	}
}

type testLease struct {
	run   func(context.Context, Job) error
	close func() error
}

func (l *testLease) Run(ctx context.Context, job Job) error { return l.run(ctx, job) }
func (l *testLease) Close() error                           { return l.close() }

func TestServeRunsUpToCapacityAndClosesAfterRuns(t *testing.T) {
	jobs := make(chan Job, 3)
	for job := Job(1); job <= 3; job++ {
		jobs <- job
	}
	close(jobs)
	started := make(chan Job, 3)
	releaseRuns := make(chan struct{})
	closed := make(chan Job, 3)
	returned := make(chan error, 1)
	go func() {
		returned <- Serve(context.Background(), jobs, 2, func(_ context.Context, job Job) (Lease, error) {
			return &testLease{
				run:   func(context.Context, Job) error { started <- job; <-releaseRuns; return nil },
				close: func() error { closed <- job; return nil },
			}, nil
		})
	}()

	first := await(t, started, "first Run")
	second := await(t, started, "second Run")
	if first == second {
		t.Fatalf("started duplicate jobs %d", first)
	}
	select {
	case job := <-started:
		t.Fatalf("job %d started beyond capacity", job)
	default:
	}
	select {
	case job := <-closed:
		t.Fatalf("job %d closed before Run completed", job)
	default:
	}
	close(releaseRuns)
	await(t, closed, "first Close")
	await(t, closed, "second Close")
	await(t, started, "third Run after capacity release")
	// The third Run needs a release signal too; the channel is already closed.
	if err := await(t, returned, "Serve return"); err != nil {
		t.Fatalf("Serve returned %v", err)
	}
	await(t, closed, "third Close")
}

func TestServeJoinsWholeCohortBeforeClosingAndCloseHoldsCapacity(t *testing.T) {
	jobs := make(chan Job, 3)
	for job := Job(1); job <= 3; job++ {
		jobs <- job
	}
	close(jobs)
	runStarted := make(chan Job, 3)
	runRelease := make(chan struct{})
	runReturned := make(chan Job, 3)
	closeStarted := make(chan Job, 3)
	closeRelease := make(chan struct{})
	thirdStarted := make(chan struct{})
	returned := make(chan error, 1)
	go func() {
		returned <- Serve(context.Background(), jobs, 2, func(_ context.Context, job Job) (Lease, error) {
			return &testLease{
				run: func(context.Context, Job) error {
					if job == 3 {
						close(thirdStarted)
					}
					runStarted <- job
					<-runRelease
					runReturned <- job
					return nil
				},
				close: func() error {
					select {
					case <-runReturned:
					default:
						return errors.New("Close began before cohort Runs returned")
					}
					closeStarted <- job
					if job == 1 {
						<-closeRelease
					}
					return nil
				},
			}, nil
		})
	}()
	await(t, runStarted, "first Run")
	await(t, runStarted, "second Run")
	close(runRelease)
	await(t, closeStarted, "first Close")
	select {
	case <-thirdStarted:
		t.Fatal("third Run started before held Close completed")
	default:
	}
	close(closeRelease)
	await(t, closeStarted, "second Close")
	await(t, thirdStarted, "third Run")
	if err := await(t, returned, "Serve return"); err != nil {
		t.Fatalf("Serve returned %v", err)
	}
}

func TestServeInputWaitIsCanceled(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	jobs := make(chan Job)
	returned := make(chan error, 1)
	go func() {
		returned <- Serve(ctx, jobs, 2, func(context.Context, Job) (Lease, error) { t.Error("unexpected Open"); return nil, nil })
	}()
	cancel()
	if err := await(t, returned, "canceled Serve"); !errors.Is(err, context.Canceled) {
		t.Fatalf("Serve error = %v, want context.Canceled", err)
	}
}

func TestServeOpenFailureStopsAndReleasesStartedWork(t *testing.T) {
	openErr := errors.New("open failed")
	started := make(chan struct{})
	runStopped := make(chan struct{})
	closed := make(chan struct{})
	jobs := make(chan Job, 2)
	jobs <- 1
	jobs <- 2
	close(jobs)
	returned := make(chan error, 1)
	var opens sync.Mutex
	count := 0
	go func() {
		returned <- Serve(context.Background(), jobs, 2, func(context.Context, Job) (Lease, error) {
			opens.Lock()
			count++
			n := count
			opens.Unlock()
			if n == 1 {
				return &testLease{
					run: func(ctx context.Context, _ Job) error {
						close(started)
						<-ctx.Done()
						close(runStopped)
						return ctx.Err()
					},
					close: func() error { close(closed); return nil },
				}, nil
			}
			<-started
			return nil, openErr
		})
	}()
	if err := await(t, returned, "Serve after Open failure"); !errors.Is(err, openErr) {
		t.Fatalf("Serve error = %v, want open failure", err)
	}
	select {
	case <-runStopped:
	default:
		t.Fatal("Run did not observe stop before Serve returned")
	}
	select {
	case <-closed:
	default:
		t.Fatal("successful lease was not closed")
	}
}

func TestServeRetainsRunAndCloseErrors(t *testing.T) {
	runErr := errors.New("run failed")
	closeErr := errors.New("close failed")
	jobs := make(chan Job, 1)
	jobs <- 1
	close(jobs)
	err := Serve(context.Background(), jobs, 1, func(context.Context, Job) (Lease, error) {
		return &testLease{run: func(context.Context, Job) error { return runErr }, close: func() error { return closeErr }}, nil
	})
	if !errors.Is(err, runErr) || !errors.Is(err, closeErr) {
		t.Fatalf("Serve error = %v, want both Run and Close failures", err)
	}
}

func TestServeAlreadyCanceledOpensNothing(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	opened := false
	err := Serve(ctx, make(chan Job), 2, func(context.Context, Job) (Lease, error) { opened = true; return nil, nil })
	if !errors.Is(err, context.Canceled) || opened {
		t.Fatalf("Serve error=%v opened=%v", err, opened)
	}
}
